<?php
if(session_status()!==PHP_SESSION_ACTIVE)session_start(); require_once __DIR__.'/database.php';
function e($x){return htmlspecialchars((string)$x,ENT_QUOTES,'UTF-8');}
function me(){return $_SESSION['user']??null;}
function auth(){if(!me()){header('Location: login.php');exit;}}
function flash($m,$t='success'){$_SESSION['flash']=[$m,$t];}
function flashes(){if(isset($_SESSION['flash'])){[$m,$t]=$_SESSION['flash'];echo '<div class="alert '.e($t).'">'.e($m).'</div>';unset($_SESSION['flash']);}}
function token(){return $_SESSION['csrf']??=bin2hex(random_bytes(32));}
function verify_token(){if(!hash_equals(token(),$_POST['csrf']??'')){http_response_code(403);exit('Token invalid. Refresh halaman.');}}
function upload_img($key,$folder){if(!isset($_FILES[$key])||$_FILES[$key]['error']===UPLOAD_ERR_NO_FILE)return null;$f=$_FILES[$key];if($f['error']!==0||$f['size']>3145728)throw new Exception('Upload gagal atau ukuran lebih dari 3 MB');$mime=(new finfo(FILEINFO_MIME_TYPE))->file($f['tmp_name']);$ext=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'][$mime]??null;if(!$ext)throw new Exception('Format file harus JPG/PNG/WEBP');$dir=__DIR__.'/../uploads/'.$folder;if(!is_dir($dir))mkdir($dir,0755,true);$n=bin2hex(random_bytes(16)).'.'.$ext;if(!move_uploaded_file($f['tmp_name'],$dir.'/'.$n))throw new Exception('Gagal menyimpan file');return 'uploads/'.$folder.'/'.$n;}
function del_img($p){if($p&&str_starts_with($p,'uploads/')){$f=__DIR__.'/../'.$p;if(is_file($f))unlink($f);}}
function headpage($title){?><!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($title)?> | DanusuProject</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{background:#fffdf4;color:#426b54;font-family:Poppins,Arial}.navbar,.panel,.card{background:white;border:0;border-radius:18px;box-shadow:0 5px 24px #335e4512}.brand{font-weight:800;color:#49715b}.hero{background:#fff6c3;border-radius:25px;padding:40px}.btn-green{background:#49715b;color:white}.btn-green:hover{background:#385846;color:white}.card img{height:190px;object-fit:cover}.alert{background:#e4f4e7;padding:12px;border-radius:10px}.alert.error{background:#ffe5e5}</style></head><body><nav class="navbar container my-3 p-3"><a class="brand navbar-brand" href="index.php">DanusuProject</a><div class="ms-auto d-flex gap-3 flex-wrap"><a href="index.php">Katalog</a><?php if(me()):?><a href="my-products.php">Produk Saya</a><a href="profile.php">Profil</a><a href="logout.php">Keluar</a><?php else:?><a href="login.php">Login</a><a href="register.php">Daftar</a><?php endif;?></div></nav><main class="container py-3"><?php flashes(); }
function footpage(){ echo '</main><footer class="container text-center py-4 text-secondary">DanusuProject · Universitas Sumatera Utara</footer></body></html>'; }
